/**
 * REGIONAL_SEK live signal - server-side port of the Python reference
 * implementation `research/src/gem/live.py::regional_live_signal`.
 *
 * The Python module is the REFERENCE. This port is verified against it by
 * tests/engine.conformance.test.ts on fixtures generated by
 * research/scripts/export_live_fixtures.py (identical status, target, reason,
 * dates; returns equal to 1e-12). Any rule change must be made in Python first,
 * fixtures regenerated, and this file updated until conformance passes.
 *
 * Rule (fixed, never optimised):
 *   1. signal period = last calendar month end strictly before as_of
 *   2. per fund: last NAV in the month must be within 3 business days of the
 *      month's last business day (else NO_SIGNAL "not complete")
 *   3. 12-month NAV return per region, point to point, both endpoints
 *      staleness-checked
 *   4. cash hurdle: Riksbank SETB3MBENCH, month-end sampled (stale > 5 bdays),
 *      12-month product of r_m = (y_{m-1}/100)/12 (operation order as in Python)
 *   5. best of USA / Europe / EM (strict >, earlier region wins ties);
 *      winner must be strictly above the hurdle, else Avanza Ränta Kort
 */

import {
  ISODate, busdayCount, lastBusinessDayOnOrBefore, monthEndMinus, monthEndOf, monthKey, previousMonthEnd,
} from "./dates";

export const STRATEGY_ID = "REGIONAL_SEK";
/** Explicit, machine-readable rule version (Python: gem.live STRATEGY_VERSION). */
export const STRATEGY_VERSION = "regional-sek-v1.0.0";
export const LOOKBACK_MONTHS = 12;
export const MAX_STALE_BDAYS_NAV = 3;
export const MAX_STALE_BDAYS_YIELD = 5;

export const REGIONS = ["usa", "europe", "em"] as const;
export type Region = (typeof REGIONS)[number];
export const REGION_TO_INSTRUMENT: Record<Region, string> = {
  usa: "AVANZA_USA",
  europe: "AVANZA_EUROPA",
  em: "AVANZA_EM",
};
export const DEFENSIVE_INSTRUMENT = "AVANZA_RANTA_KORT";

/** A dated value (NAV level or yield in percent). */
export interface Point {
  date: ISODate;
  value: number;
}

export interface EngineResult {
  strategy: string;
  strategy_version: string;
  as_of: ISODate;
  signal_period_end: ISODate;
  status: "VALID" | "NO_SIGNAL";
  target: string | null;
  returns: { usa?: number | null; europe?: number | null; em?: number | null; cash?: number | null };
  nav_dates: Record<string, ISODate | null>;
  reason: string;
  /** Diagnostics used by the pipeline (not part of the Python output). */
  endpoints: Record<string, { start_date: ISODate | null; start_nav: number | null; end_date: ISODate | null; end_nav: number | null }>;
  incomplete_instrument: string | null;
  /** Monthly cash returns inside the 12-month hurdle window (Python: diagnostics.cash_window). */
  cash_window: [ISODate, number][];
}

function sortPoints(s: Point[]): Point[] {
  return [...s].filter((p) => Number.isFinite(p.value)).sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
}

/** Last observation on/before monthEnd, with staleness test. */
function endpoint(s: Point[], me: ISODate): { value: number | null; date: ISODate | null } {
  let last: Point | null = null;
  for (const p of s) {
    if (p.date <= me) last = p;
    else break;
  }
  if (!last) return { value: null, date: null };
  const lb = lastBusinessDayOnOrBefore(me);
  if (busdayCount(last.date, lb) > MAX_STALE_BDAYS_NAV) return { value: null, date: last.date };
  return { value: last.value, date: last.date };
}

/**
 * 12-month cash return from a daily yield series (percent), exactly as
 * returns.to_month_end + yield_to_monthly_return + 12-month window in Python.
 */
export function cashHurdle12m(yields: Point[], periodEnd: ISODate): number | null {
  return cashHurdleDetail(yields, periodEnd).value;
}

/** Same as cashHurdle12m plus the monthly returns in the 12-month window (diagnostics). */
export function cashHurdleDetail(yields: Point[], periodEnd: ISODate): { value: number | null; window: [ISODate, number][] } {
  const none = { value: null, window: [] as [ISODate, number][] };
  const s = sortPoints(yields).filter((p) => p.date <= periodEnd);
  if (s.length === 0) return none;
  // month-end sampling on a complete month grid between first and last observed month
  const lastByMonth = new Map<string, Point>();
  for (const p of s) lastByMonth.set(monthKey(p.date), p);
  const first = s[0].date;
  const lastObs = s[s.length - 1].date;
  const grid: ISODate[] = [];
  for (let me = monthEndOf(first); me <= monthEndOf(lastObs); me = monthEndMinus(me, -1)) grid.push(me);
  const yAt = new Map<ISODate, number | null>();
  for (const me of grid) {
    const p = lastByMonth.get(monthKey(me));
    if (!p) {
      yAt.set(me, null);
      continue;
    }
    const stale = busdayCount(p.date, lastBusinessDayOnOrBefore(me)) > MAX_STALE_BDAYS_YIELD;
    yAt.set(me, stale ? null : p.value);
  }
  // regularize_monthly: the grid runs from the first to the last NON-missing month
  const valid = grid.filter((me) => yAt.get(me) !== null);
  if (valid.length === 0) return none;
  const g = grid.filter((me) => me >= valid[0] && me <= valid[valid.length - 1]);
  // r_m = y_{m-1}/1200 for m in grid (excluding the first), NaN dropped
  const rets: { me: ISODate; r: number }[] = [];
  for (let i = 1; i < g.length; i++) {
    const prev = yAt.get(g[i - 1]);
    // Same operation order as Python (y / 100.0, then / 12.0): prev / 1200 differs in the last bit.
    if (prev !== null && prev !== undefined) rets.push({ me: g[i], r: prev / 100 / 12 });
  }
  const from = monthEndMinus(periodEnd, LOOKBACK_MONTHS);
  const window = rets.filter((x) => x.me > from && x.me <= periodEnd);
  const w: [ISODate, number][] = window.map((x) => [x.me, x.r]);
  if (window.length !== LOOKBACK_MONTHS) return { value: null, window: w };
  return { value: window.reduce((acc, x) => acc * (1 + x.r), 1) - 1, window: w };
}

function isNum(x: number | null | undefined): x is number {
  return typeof x === "number" && Number.isFinite(x);
}

export function computeRegionalSignal(
  asOf: ISODate,
  navs: Record<string, Point[]>,
  ssvx3mYield: Point[],
): EngineResult {
  const periodEnd = previousMonthEnd(asOf);
  const lastBday = lastBusinessDayOnOrBefore(periodEnd);
  const out: EngineResult = {
    strategy: STRATEGY_ID,
    strategy_version: STRATEGY_VERSION,
    as_of: asOf,
    signal_period_end: periodEnd,
    status: "NO_SIGNAL",
    target: null,
    returns: {},
    nav_dates: {},
    reason: "",
    endpoints: {},
    incomplete_instrument: null,
    cash_window: [],
  };

  const rets: Partial<Record<Region, number | null>> = {};
  for (const region of REGIONS) {
    const iid = REGION_TO_INSTRUMENT[region];
    const raw = navs[iid];
    if (!raw || raw.length === 0) {
      out.reason = `no NAV series for ${iid}`;
      out.incomplete_instrument = iid;
      return out;
    }
    const s = sortPoints(raw);
    const now = endpoint(s, periodEnd);
    out.nav_dates[iid] = now.date;
    if (now.value === null) {
      out.reason = `month ${periodEnd.slice(0, 7)} not complete for ${iid}: last NAV ${now.date ?? "none"} (> ${MAX_STALE_BDAYS_NAV} bdays before ${lastBday})`;
      out.incomplete_instrument = iid;
      out.endpoints[iid] = { start_date: null, start_nav: null, end_date: now.date, end_nav: null };
      return out;
    }
    const then = endpoint(s, monthEndMinus(periodEnd, LOOKBACK_MONTHS));
    rets[region] = then.value === null ? null : now.value / then.value - 1;
    out.endpoints[iid] = { start_date: then.date, start_nav: then.value, end_date: now.date, end_nav: now.value };
  }
  const hurdle = cashHurdleDetail(ssvx3mYield, periodEnd);
  const cash = hurdle.value;
  out.cash_window = hurdle.window;
  out.returns = { usa: rets.usa ?? null, europe: rets.europe ?? null, em: rets.em ?? null, cash };

  // RegionalMomentumStrategy.evaluate (research/src/gem/strategies.py)
  const missing = [
    ...REGIONS.filter((r) => !isNum(rets[r])).map((r) => `${r}_return`),
    ...(isNum(cash) ? [] : ["hurdle_return"]),
  ];
  if (missing.length) {
    out.reason = `missing input(s): ${missing.join(", ")}`;
    return out;
  }
  let best: Region = REGIONS[0];
  for (const r of REGIONS.slice(1)) if ((rets[r] as number) > (rets[best] as number)) best = r;
  if ((rets[best] as number) > (cash as number)) {
    out.reason = `${best} best and > hurdle`;
    out.target = REGION_TO_INSTRUMENT[best];
  } else {
    out.reason = `best region ${best} <= hurdle -> defensive`;
    out.target = DEFENSIVE_INSTRUMENT;
  }
  out.status = "VALID";
  return out;
}
